<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import {FileUp,Play,RefreshCw,Square} from 'lucide-vue-next'
import {api,type Citation,type EvaluationCase,type EvaluationDataset,type EvaluationJob} from '../api'
import {useAppStore} from '../store'
import {modelRoles,roleLabels} from '../model-catalog'
import MessageContent from '../components/MessageContent.vue'

const store=useAppStore(),datasets=ref<EvaluationDataset[]>([]),datasetId=ref(''),dataset=ref<EvaluationDataset|null>(null)
const jobs=ref<EvaluationJob[]>([]),jobId=ref(''),job=ref<EvaluationJob|null>(null),cases=ref<EvaluationCase[]>([])
const split=ref('all'),profile=ref('current'),scopeMode=ref('documents'),documents=ref<string[]>([]),libraries=ref<string[]>([]),baseline=ref('')
const error=ref(''),notice=ref(''),busy=ref(false),refreshing=ref(false),detailsLoading=ref(false),datasetLoading=ref(false)
const jobOffset=ref(0),caseOffset=ref(0),sourceFocus=ref<Record<string,number>>({})
let alive=true,timer:ReturnType<typeof setInterval>|undefined,detailAttempt=0,datasetAttempt=0,pendingSignature='',pendingKey=''
const states:Record<string,string>={queued:'排队中',running:'运行中',cancelling:'正在取消',cancelled:'已取消',succeeded:'执行完成',failed:'执行失败'}
const kinds:Record<string,string>={grounded:'有依据回答',insufficient:'证据不足',clarification:'需要澄清',smalltalk:'闲聊'}
const metricNames:Record<string,string>={kind_correct:'回答类型正确率',citations_valid:'引用完整合法率',source_types_correct:'来源类型正确率',faithfulness:'事实忠实度',fact_coverage:'标准事实覆盖',citation_support:'引用语义支持',claim_citation_coverage:'事实引用覆盖',citation_validity:'引用编号有效率'}
const metricOrder=['kind_correct','faithfulness','fact_coverage','citations_valid','citation_support','source_types_correct']
const gateMetrics=[...metricOrder,'claim_citation_coverage']
const gateMinimum=ref<Record<string,number>>(Object.fromEntries(gateMetrics.map(name=>[name,100])))
const gateRequired=ref<Record<string,boolean>>(Object.fromEntries(gateMetrics.map(name=>[name,true])))
const maxRegression=ref(0),maxFailed=ref(0)
const selectedCases=computed(()=>dataset.value?.dataset?.cases.filter(item=>split.value==='all'||item.split===split.value)||[])
const scopeDocuments=computed(()=>store.readyDocuments.filter(item=>!item.version_info||item.version_info.is_current))
const policyValid=computed(()=>gateMetrics.every(name=>Number.isFinite(gateMinimum.value[name])&&gateMinimum.value[name]>=0&&gateMinimum.value[name]<=100)&&Number.isFinite(maxRegression.value)&&maxRegression.value>=0&&maxRegression.value<=100&&Number.isInteger(maxFailed.value)&&maxFailed.value>=0&&maxFailed.value<=selectedCases.value.length)
const canStart=computed(()=>!!dataset.value&&!datasetLoading.value&&selectedCases.value.length>0&&policyValid.value&&(scopeMode.value==='documents'?documents.value.length>0:libraries.value.length>0))
const baselines=computed(()=>jobs.value.filter(item=>item.dataset_id===datasetId.value&&item.state==='succeeded'&&item.split===split.value))
const active=(value:EvaluationJob|null)=>!!value&&['queued','running','cancelling'].includes(value.state)
const pct=(value:number|null|undefined)=>value==null?'未评分':`${(value*100).toFixed(1)}%`
const delta=(value:number|null|undefined)=>value==null?'不可比较':`${value>=0?'+':''}${(value*100).toFixed(1)} 个百分点`

async function loadDataset(){const attempt=++datasetAttempt;datasetLoading.value=true;dataset.value=null;baseline.value='';if(!datasetId.value){datasetLoading.value=false;return}
  try{const value=await api.evaluationDataset(datasetId.value);if(alive&&attempt===datasetAttempt)dataset.value=value}catch(e:any){if(alive&&attempt===datasetAttempt)error.value=e.message}finally{if(attempt===datasetAttempt)datasetLoading.value=false}}
async function loadDetails(){const attempt=++detailAttempt,id=jobId.value,offset=caseOffset.value;if(!id){job.value=null;cases.value=[];return}detailsLoading.value=true
  try{const [value,rows]=await Promise.all([api.evaluationJob(id),api.evaluationCases(id,offset)]);if(alive&&attempt===detailAttempt){job.value=value;cases.value=rows.items}}
  catch(e:any){if(alive&&attempt===detailAttempt)error.value=e.message}finally{if(attempt===detailAttempt)detailsLoading.value=false}}
async function loadJobs(){if(refreshing.value)return;refreshing.value=true
  try{const value=await api.evaluationJobs(jobOffset.value);if(!alive)return;jobs.value=value.items;if(!jobId.value&&jobs.value[0])jobId.value=jobs.value[0].id;else if(jobId.value)await loadDetails()}
  catch(e:any){if(alive)error.value=e.message}finally{refreshing.value=false}}
async function refresh(){error.value='';try{const value=await api.evaluationDatasets();if(!alive)return;datasets.value=value.items;if(!datasetId.value)datasetId.value=datasets.value[0]?.id||'';await Promise.all([store.loadDocuments(),store.loadKnowledgeBases(),loadJobs()]);if(alive){documents.value=documents.value.filter(id=>scopeDocuments.value.some(doc=>doc.id===id));libraries.value=libraries.value.filter(id=>store.knowledgeBases.some(base=>base.id===id))}}catch(e:any){if(alive)error.value=e.message}}
async function importFile(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;busy.value=true;error.value='';notice.value=''
  try{if(file.size>8_000_000)throw new Error('数据集文件不能超过 8 MB。');const imported=await api.importEvaluationDataset(JSON.parse(await file.text()));await refresh();datasetId.value=imported.id;notice.value=`已导入 ${imported.name}，共 ${imported.case_count} 题。标签不会作为知识库文档上传。`}
  catch(e:any){error.value=e instanceof SyntaxError?'数据集不是有效的 JSON 文件。':e.message}finally{busy.value=false;input.value=''}}
async function start(){if(busy.value||!canStart.value)return;busy.value=true;error.value='';notice.value=''
  const body={dataset_id:datasetId.value,split:split.value,profile:profile.value,baseline_job_id:baseline.value||null,document_ids:scopeMode.value==='documents'?documents.value:[],knowledge_base_ids:scopeMode.value==='libraries'?libraries.value:[],gate_policy:{schema_version:1,max_failed_cases:maxFailed.value,require_model_review:true,require_comparison:!!baseline.value,metric_gates:gateMetrics.map(name=>({metric:name,minimum:gateMinimum.value[name]/100,max_regression:maxRegression.value/100,required:gateRequired.value[name]}))}}
  const signature=JSON.stringify(body);if(signature!==pendingSignature||!pendingKey){pendingSignature=signature;pendingKey=crypto.randomUUID()}
  try{const value=await api.createEvaluationJob(body,pendingKey);pendingKey='';pendingSignature='';jobOffset.value=0;jobId.value=value.id;caseOffset.value=0;await loadJobs();notice.value='任务已入队，独立评测 Worker 将按冻结配置执行。'}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function cancel(){if(!job.value||busy.value)return;busy.value=true;error.value='';try{job.value=await api.cancelEvaluationJob(job.value.id);await loadJobs()}catch(e:any){error.value=e.message}finally{busy.value=false}}
function selectJob(value:EvaluationJob){if(jobId.value===value.id&&caseOffset.value===0)return;job.value=value;jobId.value=value.id;caseOffset.value=0;cases.value=[]}
async function focusEvidence(row:EvaluationCase,citation:Citation){sourceFocus.value[row.id]=citation.number;await nextTick();document.getElementById(`eval-source-${row.id}-${citation.number}`)?.scrollIntoView({behavior:'smooth',block:'nearest'})}
watch(datasetId,loadDataset);watch([jobId,caseOffset],()=>{cases.value=[];void loadDetails()});watch(jobOffset,loadJobs);watch(split,()=>{baseline.value=''})
onMounted(async()=>{if(!store.capabilities?.features.evaluation)return;await refresh();if(!alive)return;timer=setInterval(()=>{if(alive&&(jobs.value.some(active)||active(job.value)))void loadJobs()},2000)})
onUnmounted(()=>{alive=false;if(timer)clearInterval(timer)})
</script>

<template><section class="documents evaluation-page">
  <header class="page-title"><div><small>EVALUATION LAB</small><h1>让每次改进都有证据</h1><p>固定问题、冻结配置，检查真实答案与来源。</p></div><button class="secondary" :disabled="refreshing||busy" @click="refresh"><RefreshCw :size="16"/>刷新</button></header>
  <p v-if="error" class="stream-error" role="alert">{{error}}</p><p v-if="notice" class="notice" role="status">{{notice}}</p>
  <p v-if="!store.capabilities?.features.evaluation" class="empty-note">当前环境尚未开放评测工作台，请联系部署管理员。</p>
  <div v-else class="workbench-grid"><aside class="trial-setup">
    <div class="section-label">01 / 数据集与试验</div><h2>创建一轮评测</h2><p class="muted">仅使用当前账号有权访问的资料。标准答案只供评分，不会进入回答提示。</p>
    <label class="import-file secondary"><FileUp :size="16"/>导入标注 JSON<input type="file" accept=".json,application/json" :disabled="busy" aria-label="导入评测数据集" @change="importFile"/></label>
    <form @submit.prevent="start"><fieldset :disabled="busy"><label>数据集<select v-model="datasetId"><option value="" disabled>选择已导入的数据集</option><option v-for="item in datasets" :key="item.id" :value="item.id">{{item.name}} · {{item.case_count}} 题</option></select></label>
      <label>题目分组<select v-model="split"><option value="all">全部题目</option><option value="dev">开发集</option><option value="frozen">冻结集</option><option value="custom">自定义分组</option></select></label>
      <p class="muted">{{datasetLoading?'正在读取题目…':`本轮 ${selectedCases.length} 题`}}。冻结集用于最终对比，避免按题目反复调参。</p>
      <label>检索配置<select v-model="profile"><option value="baseline">基础检索</option><option value="current">当前增强配置</option></select></label>
      <p class="muted">基础检索关闭父级上下文、三级合并、Grader 与精排；当前配置沿用已启用的增强能力。</p>
      <label>资料范围<select v-model="scopeMode"><option value="documents">我的已就绪资料</option><option v-if="store.capabilities?.features.sharing" value="libraries">共享知识库</option></select></label>
      <div class="scope-list" v-if="scopeMode==='documents'"><label v-for="doc in scopeDocuments" :key="doc.id"><input v-model="documents" type="checkbox" :value="doc.id" :disabled="documents.length>=100&&!documents.includes(doc.id)"/>{{doc.original_name}}<small v-if="doc.version_info">v{{doc.version_info.version_number}}</small></label><p v-if="!scopeDocuments.length" class="muted">先在资料页上传、完成入库并发布版本。</p></div>
      <div class="scope-list" v-else><label v-for="base in store.knowledgeBases" :key="base.id"><input v-model="libraries" type="checkbox" :value="base.id" :disabled="libraries.length>=20&&!libraries.includes(base.id)"/>{{base.name}}</label><p v-if="!store.knowledgeBases.length" class="muted">当前没有可访问的共享库。</p></div>
      <label>对比基线（可选）<select v-model="baseline"><option value="">独立运行</option><option v-for="item in baselines" :key="item.id" :value="item.id">{{item.id.slice(0,8)}} · {{item.profile==='baseline'?'基础检索':'当前配置'}}</option></select></label>
      <p class="muted">可选当前任务列表中的已完成基线。服务端会核对资料、索引和审阅策略是否一致。</p>
      <details class="gate-settings"><summary>质量门禁策略</summary><p class="muted">阈值在创建时冻结。要求完整评分的指标不会用缺失值冒充达标；不适用的指标单独标明。</p>
        <div v-for="name in gateMetrics" :key="name" class="gate-row"><label>{{metricNames[name]}}最低 / %<input v-model.number="gateMinimum[name]" type="number" min="0" max="100" step="0.1" required :aria-label="`${metricNames[name]}最低百分比`"/></label><label class="check"><input v-model="gateRequired[name]" type="checkbox"/>要求完整评分</label></div>
        <label>允许回退 / 百分点（有基线时）<input v-model.number="maxRegression" type="number" min="0" max="100" step="0.1" required/></label><label>允许执行失败题数<input v-model.number="maxFailed" type="number" min="0" :max="selectedCases.length" step="1" required/></label>
      </details>
    </fieldset><button class="primary start-trial" :disabled="busy||!canStart"><Play :size="16"/>创建并运行 {{selectedCases.length}} 题</button></form>
    <p class="cost-note">开始后将调用回答与评测模型。任务创建时冻结资料范围、模型版本和检索配置。</p>
  </aside><main class="trial-results">
    <header class="results-heading"><div><div class="section-label">02 / 我的任务</div><h2>运行与结果</h2></div><span class="muted">仅显示当前账号的评测</span></header>
    <div class="table-wrap"><table><thead><tr><th>任务 / 配置</th><th>进度</th><th>状态</th><th>质量门禁</th></tr></thead><tbody><tr v-for="item in jobs" :key="item.id" :class="{selected:jobId===item.id}"><td><button class="job-link" @click="selectJob(item)">{{item.id.slice(0,8)}}</button><small>{{item.profile==='baseline'?'基础检索':'当前增强配置'}} · {{item.split}}</small></td><td><progress :max="item.total_cases" :value="item.completed_cases" :aria-label="`任务 ${item.id.slice(0,8)} 进度`"/><small>{{item.completed_cases}} / {{item.total_cases}}</small></td><td>{{states[item.state]}}</td><td><span v-if="item.report" :class="item.report.gate_passed?'pass':'fail'">{{item.report.gate_passed?'通过':'未通过'}}</span><span v-else class="muted">尚无报告</span></td></tr><tr v-if="!jobs.length"><td colspan="4" class="muted">还没有评测任务。从左侧导入标注并选择资料开始。</td></tr></tbody></table></div>
    <nav class="pager" aria-label="评测任务分页"><button class="secondary" :disabled="refreshing||jobOffset===0" @click="jobOffset=Math.max(0,jobOffset-20)">上一页</button><span>第 {{Math.floor(jobOffset/20)+1}} 页</span><button class="secondary" :disabled="refreshing||jobs.length<20" @click="jobOffset+=20">下一页</button></nav>
    <section v-if="job" class="job-detail" :aria-busy="detailsLoading"><header class="results-heading"><div><div class="section-label">03 / 任务详情</div><h2>{{job.id.slice(0,8)}} <span class="job-state">{{states[job.state]}}</span></h2></div><button v-if="active(job)" class="secondary stop-trial" :disabled="busy||job.state==='cancelling'" @click="cancel"><Square :size="14"/>{{job.state==='cancelling'?'正在停止':'取消评测'}}</button></header>
      <p v-if="job.error_code" class="stream-error" role="alert">{{job.error_code}}</p>
      <p class="muted">修订 {{job.model_configuration_revision}} · {{job.document_ids.length}} 份冻结资料 · {{job.completed_cases}} / {{job.total_cases}} 题已处理</p>
      <dl class="frozen-models"><div v-for="role in modelRoles" :key="role"><dt>{{roleLabels[role]}}</dt><dd>{{job.models[role].model_name}}<small>{{job.models[role].id}} · v{{job.models[role].version}}</small></dd></div></dl>
      <template v-if="job.report"><p class="gate-note" :class="job.report.gate_passed?'pass':'fail'">质量门禁{{job.report.gate_passed?'通过':'未通过'}}。任务执行完成表示本轮已结束，质量结果以评分与门禁为准。</p>
        <details><summary>查看本轮门禁判定与冻结阈值</summary><ul class="gate-checks"><li v-for="check in job.report.gate_checks" :key="check.name"><span>{{metricNames[check.name]||({execution_failures:'执行失败题数',model_review:'完整模型审阅',comparison:'基线对比要求'} as Record<string,string>)[check.name]||check.name}}</span><strong :class="check.passed?'pass':'fail'">{{check.reason==='not_applicable'?'不适用':check.passed?'通过':'未通过'}}</strong><small v-if="check.eligible_cases!=null">{{check.scored_cases??0}} / {{check.eligible_cases}} 题已评分</small><small v-if="metricNames[check.name]">实际 {{pct(check.value)}}<template v-if="check.minimum!=null"> · 最低 {{pct(check.minimum)}}</template><template v-if="check.maximum!=null"> · 最高 {{pct(check.maximum)}}</template><template v-if="job.baseline_job_id&&check.max_regression!=null"> · 允许回退 {{(check.max_regression*100).toFixed(1)}} 个百分点</template></small></li></ul><p class="muted">允许执行失败 {{job.gate_policy.max_failed_cases}} 题 · {{job.gate_policy.require_model_review?'要求完整模型审阅':'模型审阅不作强制门禁'}} · {{job.gate_policy.require_comparison?'必须有基线对比':'允许独立运行'}}</p></details>
        <div class="metrics"><article v-for="name in metricOrder" :key="name"><small>{{metricNames[name]}}</small><strong>{{pct(job.report.summary.metrics[name]?.value)}}</strong><span>{{job.report.summary.metrics[name]?.scored_cases||0}} 题已评分</span><em v-if="job.report.comparison">{{delta(job.report.comparison.metric_deltas[name])}}</em></article></div>
        <p v-if="job.report.comparison?.review_policy_changed" class="stream-error">本轮实际审阅策略发生变化，相关语义指标不计算差值。</p>
        <p class="muted">中位耗时 {{job.report.timing.median_ms??'未知'}} ms · P95 {{job.report.timing.p95_ms??'未知'}} ms（包含恢复等待）<br/>模型调用 {{job.report.usage.model_attempts}} 次 · 已报告 Token {{job.report.usage.reported_total_tokens??'未知'}} · 用量覆盖 {{job.report.usage.reported_calls}} / {{job.report.usage.model_attempts}} 次</p>
      </template>
      <h3>逐题答案与审阅</h3><p v-if="detailsLoading&&!cases.length" role="status" class="muted">正在读取逐题结果…</p><article v-for="row in cases" :key="row.id" class="case-card"><header><span>{{row.position+1}} / {{row.case_id}} · {{row.label.category}}</span><span>{{states[row.state]||row.state}}</span></header><h4>{{row.label.question}}</h4><p v-if="row.error_code" class="stream-error">{{row.error_code}}</p>
        <template v-if="row.prediction"><small class="answer-kind">{{kinds[row.prediction.kind]||row.prediction.kind}} · {{row.prediction.provider}} / {{row.prediction.model}}</small><MessageContent :content="row.prediction.answer" :citations="row.prediction.citations" @citation="focusEvidence(row,$event)"/>
          <div class="case-metrics" v-if="row.result"><span v-for="name in ['kind_correct','faithfulness','fact_coverage','citations_valid']" :key="name">{{metricNames[name]}} {{pct(row.result.metrics[name])}}</span></div>
          <details><summary>标准事实与参考答案（仅供评测）</summary><p>{{row.label.reference_answer||'未提供参考答案'}}</p><ul><li v-for="fact in row.label.expected_facts" :key="fact">{{fact}}</li></ul></details>
          <details v-if="row.review"><summary>逐事实审阅</summary><p class="muted">实际审阅模型：{{row.review.judge_provider}} / {{row.review.judge_model}}</p><div v-for="(claim,index) in row.review.claims" :key="index" class="claim"><p>{{claim.text}}</p><strong>{{({supported:'有证据支持',unsupported:'缺少支持',contradicted:'与证据冲突',unverifiable:'无法核实'} as Record<string,string>)[claim.verdict]||claim.verdict}}</strong><blockquote v-for="(quote,q) in claim.quotes" :key="q">[{{quote.number}}] {{quote.text}}</blockquote></div><p v-if="!row.review.claims.length" class="muted">该回答没有需要核查的事实主张。</p></details>
          <details v-for="evidence in row.prediction.evidence" :key="evidence.citation.number" :id="`eval-source-${row.id}-${evidence.citation.number}`" :open="sourceFocus[row.id]===evidence.citation.number"><summary>[{{evidence.citation.number}}] {{evidence.citation.source_name||evidence.citation.title||'真实来源'}}</summary><p class="evidence-content">{{evidence.content}}</p><small v-if="evidence.citation.excel_source">{{evidence.citation.excel_source.sheet_name}} · 第 {{evidence.citation.excel_source.row_start}}–{{evidence.citation.excel_source.row_end}} 行</small></details>
        </template><p v-else class="muted">{{active(job)?'等待 Worker 保存本题结果。':'本题没有生成答案。'}}</p>
      </article><nav class="pager" aria-label="逐题结果分页"><button class="secondary" :disabled="detailsLoading||caseOffset===0" @click="caseOffset=Math.max(0,caseOffset-10)">上一页</button><span>{{caseOffset+1}}–{{Math.min(caseOffset+10,job.total_cases)}} / {{job.total_cases}}</span><button class="secondary" :disabled="detailsLoading||caseOffset+10>=job.total_cases" @click="caseOffset+=10">下一页</button></nav>
    </section>
  </main></div>
</section></template>

<style scoped>
.gate-settings label{display:grid;gap:7px;font-size:11px;margin:12px 0}.gate-settings input[type=number]{width:100%;padding:8px;border:1px solid var(--line);border-radius:5px;background:var(--surface);color:var(--ink)}.gate-settings .check{display:flex;align-items:center;gap:6px;color:var(--muted)}.gate-row{border-bottom:1px solid var(--line)}.gate-checks{list-style:none;padding:0}.gate-checks li{display:flex;align-items:center;gap:12px;flex-wrap:wrap;padding:8px 0}.gate-checks small{color:var(--muted)}pre{max-height:240px;overflow:auto;font-size:10px}.evaluation-page{max-width:1560px;margin:auto}.workbench-grid{display:grid;grid-template-columns:310px minmax(0,1fr);gap:36px;align-items:start;margin-top:30px}.trial-setup{padding:24px;background:var(--surface);border:1px solid var(--line);border-radius:9px}.section-label{font-size:10px;letter-spacing:.13em;color:var(--green);font-weight:600}h2{font:600 23px 'Noto Serif SC',serif;margin:12px 0}h3{font:600 19px 'Noto Serif SC',serif;margin:28px 0 18px}.muted,.cost-note{color:var(--muted);font-size:12px;line-height:1.8}.import-file{position:relative;display:flex;gap:8px;align-items:center;justify-content:center;margin:20px 0;overflow:hidden}.import-file input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%}fieldset{border:0;margin:0;padding:0;min-width:0}fieldset>label{display:grid;gap:8px;font-size:12px;margin:18px 0 10px}select{width:100%;min-width:0;border:1px solid var(--line);border-radius:6px;padding:10px;background:var(--surface);color:var(--ink)}.scope-list{max-height:200px;overflow:auto;padding:10px 0;border-bottom:1px solid var(--line)}.scope-list label{display:flex;gap:8px;align-items:flex-start;font-size:12px;line-height:1.7;padding:7px 0;overflow-wrap:anywhere}.scope-list input{accent-color:var(--green)}.start-trial{width:100%;margin-top:22px}.cost-note{border-top:1px solid var(--line);padding-top:15px;margin-bottom:0}.notice,.gate-note{padding:14px 18px;background:var(--green2);border-radius: